  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {n['id']: n for n in nodes}

    # set of node ids that must be retained (non-removable and their ancestors)
    retained = set()
    for n in nodes:
        if not n['removable']:
            # add the node and all its ancestors
            cur = n['id']
            while cur is not None:
                retained.add(cur)
                cur = node_map[cur]['parent']

    # coverage of required symbols by currently retained nodes
    def covered_set(node_ids):
        return {node_map[nid]['symbol'] for nid in node_ids}
    covered = covered_set(retained)
    missing = [s for s in required_symbols if s not in covered]

    while missing:
        best_node = None
        best_cost = float('inf')
        best_to_add = set()

        for sym in missing:
            for nid, node in node_map.items():
                if node['symbol'] == sym and nid not in retained and node['removable']:
                    # compute added cost for this candidate
                    cost = 0.0
                    to_add = set()
                    cur = nid
                    while cur is not None and cur not in retained:
                        cost += node_map[cur]['utility']
                        to_add.add(cur)
                        cur = node_map[cur]['parent']
                    if cost < best_cost or (cost == best_cost and nid < best_node):
                        best_cost = cost
                        best_node = nid
                        best_to_add = to_add

        if not best_to_add:
            break

        retained.update(best_to_add)
        covered = covered_set(retained)
        missing = [s for s in required_symbols if s not in covered]

    all_ids = {n['id'] for n in nodes}
    removed = list(all_ids - retained)
    retained_list = list(retained)
    removed.sort()
    retained_list.sort()

    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_list
    }
